Read-only check of Yandex Disk access​ and root listing — T='[скрыто]'
api(){ curl -s -m 60 -w '\nHTTP %{http_code}\n' -H "Authorization​: OAuth $T" "https://cloud-api.yandex.net/v1/disk$1"; }
echo "--- disk info"; api "" | python3 -I -c "
import sys,json
raw=sys.stdin.read(); body,_,code=raw.rpartition('\nHTTP ')
print('HTTP',code.strip())
try:
  d=json.loads(body); print({k:d.get(k) for k in ['total_space','used_space','trash_size','is_paid','user'] if k!='user'}); print('user:',d.get('user',{}).get('display_name'))
except Exception as e: print(body[:300])
"
echo "--- root listing"; api​ "/resources?path=/&limit=100&fields=_embedded.items.name,_embedded.items.type,_embedded.items.size,_embedded.items.modified" | python3 -I -c "
import sys,json
raw=sys.stdin.read(); body,_,code=raw.rpartition('\nHTTP ')
print('HTTP',code.strip())
try:
  d=json.loads(body)
  for i in d['_embedded']['items']: print(i['type'],i['name'],i.get('size'),i['modified'][:10])
except Exception as e: print(body[:400])
"

